/** Actual saved draft/inventory normalization, independently captured before native staging. */
public final class ProgrammerSavedLegacyChecks {
 private static ProgrammerTile seed(int profile){ProgrammerTile tile=new ProgrammerTile();if(profile==1){tile.setInventorySlotContents(0,new ItemStack(ModItems.DATA_CHIP,1,3));tile.setInventorySlotContents(1,new ItemStack(ModItems.ACCESS_CARD));}if(profile==2){tile.setInventorySlotContents(0,new ItemStack(ModItems.ACCESS_CARD,1,5));tile.setInventorySlotContents(1,journal(2));}if(profile==3){tile.setInventorySlotContents(1,journal(1));tile.setInventorySlotContents(2,journal(2));}if(profile==4){tile.setInventorySlotContents(0,journal(4));tile.setInventorySlotContents(1,new ItemStack(ModItems.ACCESS_CARD,1,3));tile.setInventorySlotContents(2,new ItemStack(ModItems.ACCESS_CARD,1,1));}if(profile==5)tile.setInventorySlotContents(1,new ItemStack(ModItems.DATA_CHIP));return tile;}
 private static ItemStack journal(int company){ItemStack chip=new ItemStack(ModItems.DATA_CHIP,1,company);ChipJournal.write(chip,true,"Saved Journal",new String[]{"Committed text"});return chip;}
 private static JsonArray stacks(ProgrammerTile tile){JsonArray rows=new JsonArray();for(int slot=0;slot<3;slot++)rows.add(tile.getStackInSlot(slot).writeToNBT(new NBTTagCompound()).toString());return rows;}
 public static void main(String[] args)throws Exception{net.minecraft.init.Bootstrap.register();net.minecraftforge.fml.common.registry.GameRegistry.registerTileEntity(ProgrammerTile.class,new ResourceLocation("vandorlabs:data_chip_programmer"));net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(ModItems.ACCESS_CARD);net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(ModItems.DATA_CHIP);JsonArray cases=new JsonArray();String huge=String.join("",Collections.nCopies(700,"x"));for(int profile=0;profile<6;profile++)for(int writing:new int[]{-20,0,1,19,20,21,Integer.MAX_VALUE})for(int complete:new int[]{-20,0,1,59,60,61,Integer.MAX_VALUE})for(boolean journal:new boolean[]{false,true})for(int pageType=0;pageType<3;pageType++)for(boolean stringTitle:new boolean[]{false,true}){NBTTagCompound raw=seed(profile).writeToNBT(new NBTTagCompound());raw.setInteger("Writing",writing);raw.setInteger("Complete",complete);raw.setBoolean("Journal",journal);if(stringTitle)raw.setString("Title",huge);else raw.setInteger("Title",17);if(pageType==0){NBTTagList pages=new NBTTagList();for(int page=0;page<10;page++)pages.appendTag(new NBTTagString(huge));raw.setTag("Pages",pages);}else if(pageType==1){NBTTagList pages=new NBTTagList();pages.appendTag(new NBTTagInt(17));raw.setTag("Pages",pages);}else raw.setTag("Pages",new NBTTagCompound());NBTTagCompound opaque=new NBTTagCompound();opaque.setString("ImportedExtension","unchanged");raw.setTag("ForeignSettings",opaque);String original=raw.toString();ProgrammerTile tile=new ProgrammerTile();tile.readFromNBT(raw);JsonObject row=new JsonObject();row.addProperty("profile",profile);row.addProperty("raw",original);row.addProperty("journal",tile.journal);row.addProperty("vehicle",tile.vehicle);row.addProperty("title",tile.title);JsonArray pages=new JsonArray();for(String page:tile.pages)pages.add(page);row.add("pages",pages);row.add("items",stacks(tile));NBTTagCompound saved=tile.writeToNBT(new NBTTagCompound());row.addProperty("writing",saved.getInteger("Writing"));row.addProperty("complete",saved.getInteger("Complete"));row.addProperty("status",tile.getProgrammerStatus().name());if(!original.equals(raw.toString()))throw new AssertionError("Source decoder mutated input");cases.add(row);}JsonObject root=new JsonObject();root.addProperty("schema",1);root.add("cases",cases);StringBuilder golden=new StringBuilder();for(byte value:java.security.MessageDigest.getInstance("SHA-256").digest(root.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)))golden.append(String.format(Locale.ROOT,"%02x",value&255));if(cases.size()!=3528||!golden.toString().equals("c9fab72182445314cc7f6999ac818f586df26e733ad50ebdfef59335c5a19de3"))throw new AssertionError("Released programmer saved corpus changed: "+golden);root.addProperty("golden",golden.toString());Path output=Paths.get(System.getProperty("vandorlabs.programmerSavedReference","build/test-artifacts/programmer-saved-forge.json"));Files.createDirectories(output.toAbsolutePath().getParent());try(java.io.Writer writer=Files.newBufferedWriter(output)){new Gson().toJson(root,writer);}System.out.println("Actual programmer saved Source PASS cases="+cases.size()+" golden="+golden);}
}
